create or replace function public.osmar_review_3x_submission(p_submission_id uuid,p_decision text,p_review_note text default null) returns boolean language plpgsql security definer set search_path='' as $$ declare v_submission public.challenge_submissions%rowtype; v_points integer; v_slug text; begin if auth.uid() is null or coalesce(auth.jwt()->'app_metadata'->>'role','')<>'osmar_admin' then raise exception 'OSMAR administrator access required'; end if; if p_decision is null or p_decision not in ('approved','revision_requested','rejected') then raise exception 'Invalid review decision'; end if; if p_review_note is not null and char_length(p_review_note)>2000 then raise exception 'Review note too long'; end if; select * into v_submission from public.challenge_submissions where id=p_submission_id and status='pending' for update; if not found then raise exception 'Pending submission not found'; end if; update public.challenge_submissions set status=p_decision,review_note=nullif(btrim(p_review_note),''),reviewed_by=auth.uid(),reviewed_at=now() where id=p_submission_id; if p_decision='approved' then select c.points_award,c.slug into v_points,v_slug from public.challenge_projects p join public.challenge_catalog c on c.id=p.challenge_id where p.id=v_submission.project_id; update public.challenge_projects set status='approved',updated_at=now() where id=v_submission.project_id; if coalesce(v_points,0)>0 then perform public.osmar_award_points(v_submission.user_id,v_points,'Approved 3X challenge: '||v_slug,'challenge','3x:'||v_submission.id::text); end if; elsif p_decision='revision_requested' then update public.challenge_projects set status='revision_requested',updated_at=now() where id=v_submission.project_id; else update public.challenge_projects set status='draft',updated_at=now() where id=v_submission.project_id; end if; return true; end; $$;